// ============================================
// SCORING LOCAL (sans API, gratuit)
// Copié depuis scripts/scoring.js
// ============================================

function scoreLead(lead) {
  const breakdown = {
    company_size: scoreCompanySize(lead.company_size),
    job_title: scoreJobTitle(lead.job_title),
    industry: scoreIndustry(lead.company_industry),
    buying_signals: 5, // Par défaut, signaux non détectés
    accessibility: scoreAccessibility(lead)
  };
  const total = Object.values(breakdown).reduce((s, v) => s + v, 0);
  const label = total >= 70 ? 'chaud' : total >= 40 ? 'tiede' : 'froid';
  return { score: Math.min(total, 100), label, breakdown, priority: label === 'chaud' ? 1 : label === 'tiede' ? 2 : 3 };
}

function scoreCompanySize(size) {
  const num = parseInt(size);
  if (isNaN(num)) return 5;
  if (num <= 10) return 5;
  if (num <= 50) return 15;
  if (num <= 200) return 20;
  if (num <= 500) return 15;
  return 5;
}

function scoreJobTitle(title) {
  if (!title) return 3;
  const t = title.toLowerCase();
  if (/\b(ceo|founder|pdg|dg|président|fondateur)\b/.test(t)) return 25;
  if (/\b(vp|vice)\b/.test(t)) return 22;
  if (/\b(directeur|director|head of)\b/.test(t)) return 20;
  if (/\b(manager|responsable|lead)\b/.test(t)) return 12;
  if (/\b(stagiaire|intern|student)\b/.test(t)) return 0;
  return 5;
}

function scoreIndustry(industry) {
  if (!industry) return 3;
  const i = industry.toLowerCase();
  if (/saas|software|tech/.test(i)) return 20;
  if (/agence|agency|digital|marketing/.test(i)) return 18;
  if (/e-commerce|ecommerce/.test(i)) return 17;
  if (/conseil|consulting|b2b/.test(i)) return 15;
  if (/finance|immobilier/.test(i)) return 10;
  return 5;
}

function scoreAccessibility(lead) {
  let s = 0;
  if (lead.email && lead.email_verified) s += 8;
  else if (lead.email) s += 4;
  if (lead.linkedin_url) s += 4;
  if (lead.phone) s += 3;
  return Math.min(s, 15);
}

// Traiter tous les leads
return $input.all().map(item => {
  const lead = item.json;
  const result = scoreLead(lead);
  return {
    json: {
      id: lead.id,
      first_name: lead.first_name,
      last_name: lead.last_name,
      email: lead.email,
      job_title: lead.job_title,
      company_name: lead.company_name,
      company_industry: lead.company_industry,
      company_size: lead.company_size,
      company_description: lead.company_description,
      ...result
    }
  };
});
